        let mut app = App::new();
        app.add_message::<AppExit>().init_resource::<ButtonInput<MouseButton>>().init_resource::<crate::native_endgame_ui::View>()
            .insert_resource(connection).insert_resource(crate::Match { snapshot: Some(game.snapshot()), ..default() })
