        self.next_id += 1;
        self.players.insert(
            id,
            Champion {
                id,
                champion: name.into(),
                team,
                position,
                facing: None,
                height: self.navigation.ground(position).unwrap(),
                health: def.health,
                max_health: def.health,
                mana: def.mana,
                max_mana: None,
                level: 1,
                experience: 0.,
                score: Default::default(),
                gold: shop::starting_gold(),
                inventory: [None; 6],
                inventory_counts: [0; 6],
                respawn_at: None,
                ranks: [0; 4],
                cooldowns: [0; 4],
                cooldown_totals: [None; 4],
                effects: spells::Effects::default(),
                shields: Vec::new(),
                slows: Vec::new(),
                stuns: Vec::new(),
