    }
    pub fn command(&mut self, id: u32, action: Action) -> Result<(), String> {
        if self.winner.is_some() {
            return Err("match ended".into());
        }
        let player = self.players.get(&id).ok_or("unknown player")?;
        if player.health <= 0. {
            return Err("champion dead".into());
        }
        if stuns::active(player,self.tick) && matches!(&action,Action::Move{..}|Action::Attack{..}) {return Err("champion stunned".into());}
        if trundle_e::champion_forced(player,self.tick) && matches!(&action,Action::Move{..}|Action::Attack{..}|Action::Stop|Action::Cast{..}|Action::CastAt{..}|Action::Summoner{..}|Action::SummonerTarget{..}|Action::UseItem{..}) {return Err("champion in forced movement".into());}
        if (self.ezreal_e_casting(id) || self.ezreal_r_casting(id)) && matches!(&action,Action::Move{..}|Action::Attack{..}|Action::Stop|Action::Cast{..}|Action::CastAt{..}) {return Err("skill blocked during cast".into());}
        let resets_cached_completion = matches!(&action, Action::Stop | Action::Cast { .. }
            | Action::CastAt { .. } | Action::Summoner { .. } | Action::SummonerTarget { .. }
            | Action::UseItem { .. });
        match action {
            Action::Buy { item } => self.buy_item(id, item)?,
            Action::Sell { slot } => self.sell_item(id, slot)?,
            Action::UseItem { slot } => self.use_item(id, slot)?,
            Action::SwapItems { from, to } => self.swap_items(id, from, to)?,
            Action::SwapItemsChecked { from, to, expected_inventory, expected_counts } =>
                self.swap_items_checked(id, from, to, expected_inventory, expected_counts)?,
            Action::Summoner { slot } => self.cast_summoner(id, slot)?,
            Action::SummonerTarget { slot, target } => self.cast_summoner_on(id, slot, target)?,
            Action::Learn { slot } => self.learn(id, slot)?,
            Action::Cast { slot, target } => self.cast(id, slot, target)?,
            Action::CastAt {slot,point} => self.cast_at(id,slot,point)?,
            Action::Move { point } => {
                if player.effects.ultimate.is_some() {
                    return Err("casting ultimate".into());
                }
                if self.ally_move_is_repeat(id, point) { return Ok(()); }
                let path = self
                    .dynamic_path(player.position, point)
                    .ok_or("destination unreachable")?;
                self.cancel_windup(id)?;
                let p = self.players.get_mut(&id).unwrap();
                p.destination = Some(point);
                p.path = path;
                p.target = None;
                self.note_ally_move(id, point);
            }
            Action::Attack { target } => {
                if player.effects.ultimate.is_some() || self.tick < player.effects.spin_until {
                    return Err("attacks disabled during cast".into());
                }
                let enemy = self.target_info(target).ok_or("unknown target")?;
                if self.protected(target) {
                    return Err("target protected".into());
                }
                if enemy.team == player.team || enemy.health <= 0. {
                    return Err("invalid enemy target".into());
                }
                if !self.visible_to(player.team, target) {
                    return Err("target not visible".into());
                }
                // Every repeated attack has passed the same validity/cast/FoW guards.
                if player.target == Some(target)
                    && !player.windup.as_ref().is_some_and(|w| w.target != target) { return Ok(()); }
                let destination = enemy.position;
                let p = self.players.get_mut(&id).unwrap();
                if p.windup.as_ref().is_some_and(|w| w.target != target) {
                    self.cancel_windup(id)?;
                }
                let p = self.players.get_mut(&id).unwrap();
                p.target = Some(target);
                p.path.clear();
                p.destination = None;
                p.next_repath = 0;
                self.note_ally_pursuit(id, target, destination);
            }
            Action::Stop => {
                if player.effects.ultimate.is_some() {
                    return Err("ultimate cannot be cancelled".into());
                }
                self.cancel_windup(id)?;
                let p = self.players.get_mut(&id).unwrap();
                p.path.clear();
                p.destination = None;
                p.target = None;
            }
        }
        if resets_cached_completion && self.players[&id].destination.is_none()
            && self.players[&id].target.is_none() {
            self.ally_occupancy.clear_order(id);
        }
        Ok(())
    }
    pub fn advance(&mut self) {
        if self.winner.is_some() {
            self.clear_ezreal_q();
            self.clear_ezreal_w();
            self.clear_ezreal_e();
            self.clear_ezreal_r();
            self.clear_ezreal_passive();
            self.clear_trundle_r_terminal();
            self.clear_trundle_e();
            self.capture_final_results();
            return;
        }
        self.tick += 1;
        self.accepted_casts.prune(self.tick);
        self.ezreal_q.impacts.prune(self.session,self.tick);
        self.ezreal_r.impacts.prune(self.session,self.tick);
        self.ezreal_r.cast_audio.prune(self.session,self.tick);
        // Visual phase follows the authoritative tick even when advance_world
        // ends the match before the remaining interaction systems run.
        if let Some(i) = &mut self.interactions { i.state.nexus_crystal.advance(self.tick); }
        self.advance_shields();
        self.advance_slows();
        self.advance_stuns();
        self.advance_trundle_e();
        self.advance_pet_orders();
        self.advance_world();
        if self.winner.is_some() {
            self.clear_ezreal_q();
            self.clear_ezreal_w();
            self.clear_ezreal_e();
            self.clear_ezreal_r();
            self.clear_ezreal_passive();
            self.clear_trundle_r_terminal();
            self.clear_trundle_e();
            self.capture_final_results();
            return;
        }
        self.advance_passive_gold();
        self.advance_respawns();
        self.advance_ignite();
        // RECONSTRUCTION: timed R after Ignite and before potions/other spells.
        self.advance_trundle_r();
        self.advance_consumables();
        self.advance_interactions();
        self.advance_spells();
        self.advance_annie();
        self.advance_annie_w();
        self.advance_annie_r();
        self.prune_ezreal_passive(); // Expire before accepted ability hits of this tick.
        self.advance_ezreal_q();
        self.advance_ezreal_w();
        self.advance_ezreal_e();
        self.advance_ezreal_r();
        self.advance_pet_aura();
        self.advance_regeneration();
        self.advance_pursuit();
        self.advance_allied_motion();
        self.advance_attacks();
    }
    pub fn snapshot(&self) -> Snapshot {
        Snapshot {
            death_recap: None, // no authenticated victim in generic/legacy snapshots
            accepted_casts: None, // no authenticated viewing team in the internal snapshot
            ezreal_q_accepted_impacts: None,
            ezreal_r_accepted_impacts: None,
            ezreal_r_accepted_casts: None,
            trundle_e_pillars: self.trundle_e_projection(None),
            projectiles: self.projectiles.clone(),
            spell_projectiles: self.spell_projectiles.clone(),
            ezreal_q_projectiles: self.ezreal_q_projection(None),
            ezreal_r_projectiles: Vec::new(), // no authenticated audience here
            ezreal_r_current_heights: None, // only snapshot_for_atomic supplies current Y
            ezreal_w_current_missiles: None, // OLSR current W only
            ezreal_e_accepted_releases: None, // no authenticated atomic audience
            ezreal_e_current_bolts: None,
            ezreal_r_casts: Vec::new(), // no authenticated caster audience here
            ezreal_w_casts: Vec::new(),
            ezreal_e_casts: Vec::new(), // W pending has the same body-visible audience
            ezreal_passive_self: None,
            roster: self
                .players
                .values()
                .map(|p| vision::RosterEntry {
                    id: p.id,
                    champion: p.champion.clone(),
                    team: p.team,
                    score: p.score,
                })
                .collect(),
            session: self.session,
            tick: self.tick,
            players: self.players.values().map(|p| {let mut state=p.clone();state.max_mana=Some(self.stats(p.id).max_mana);state}).collect(),
            units: self.units.values().map(|unit| {
                let mut unit = unit.clone();
                unit.attack_presentation = if vilemaw_attacks::is_vilemaw(&unit) { self.vilemaw_attacks.active(unit.id) } else { None };
                unit
            }).collect(),
            winner: self.winner,
            result:self.final_result.clone(),
            kill_events: self.kill_rewards.events.iter().cloned().collect(),
            // Omniscient/debug snapshot; network callers must use snapshot_for.
            attack_events: self.attack_presentation.events(),
            attack_presentation_error: self.attack_presentation_error.clone(),
            vilemaw_attack_events: self.vilemaw_attacks.events(),
            vilemaw_attack_presentation_error: self.vilemaw_attacks.error().map(str::to_owned),
            map10: self.interactions.as_ref().map(|i| i.state.clone()),
        }
    }
